+  { timeout: 10_000 },
+  async () => {
+    const MAX_DURATION_MS = 500;
+
+    const onConnection = vi.fn<() => void>();
+    const results: number[] = [];
+    let deferred: Deferred<void> = createDeferred();
+
+    const t = initTRPC.create({
+      transformer: superjson,
+      sse: {
+        maxDurationMs: MAX_DURATION_MS,
+      },
+    });
+
+    const router = t.router({
+      sub: t.procedure
+        .input(
+          z
+            .object({
+              lastEventId: z.coerce.number().min(0).optional(),
+            })
+            .optional(),
+        )
+        .subscription(async function* (opts) {
+          onConnection();
+          let idx = opts.input?.lastEventId ?? 0;
+          while (!opts.signal?.aborted) {
+            idx++;
+            await deferred.promise;
+            deferred = createDeferred();
+            yield tracked(String(idx), idx);
+          }
+        }),
+    });
+
+    const linkSpy: TRPCLink<typeof router> = () => {
+      return ({ next, op }) => {
+        return observable((observer) => {
+          const unsubscribe = next(op).subscribe({
+            next(envelope) {
+              if (!envelope.result.type || envelope.result.type === 'data') {
+                results.push((envelope.result.data as any).data);
+              }
+              observer.next(envelope);
+            },
+            error: observer.error,
+            complete: observer.complete,
+          });
+          return unsubscribe;
+        });
+      };
+    };
+
+    await using ctx = testServerAndClientResource(router, {
+      server: {},
+      client(opts) {
+        return {
+          links: [
+            linkSpy,
+            httpSubscriptionLink({
+              url: opts.httpUrl,
+              transformer: superjson,
+            }),
+          ],
+        };
+      },
+    });
+
+    const onError = vi.fn();
+    const onComplete = vi.fn();
+    const sub = ctx.client.sub.subscribe(undefined, {
+      onError,
+      onComplete,
+    });
+
+    // Wait for initial connection
+    await vi.waitFor(() => {
+      expect(onConnection).toHaveBeenCalledTimes(1);
+    });
+
+    // Send some data before maxDurationMs fires
+    deferred.resolve();
+
+    await vi.waitFor(() => {
+      expect(results).toHaveLength(1);
+    });
+    expect(results).toEqual([1]);
+
+    // Wait for maxDurationMs to fire (500ms), then the polyfill's
+    // retry delay (min 1000ms), then the reconnection to complete.
+    await suppressLogsUntil(async () => {
+      await vi.waitFor(
+        () => {
+          expect(onConnection).toHaveBeenCalledTimes(2);
+        },
+        { timeout: 5_000 },
+      );
+    });
+
+    // Send more data on the new connection
+    deferred.resolve();
+
+    await vi.waitFor(() => {
+      expect(results).toHaveLength(2);
+    });
+    // tracked() ensures the second connection resumes from lastEventId
+    expect(results).toEqual([1, 2]);
+
+    // Subscription should NOT have errored or completed
+    expect(onError).not.toHaveBeenCalled();
+    expect(onComplete).not.toHaveBeenCalled();
+
+    sub.unsubscribe();
+  },
+);

pr_body:
Closes #6701

## 🎯 Changes

#6701 provides a helpful codesandbox reproducing `useSuspenseInfiniteQuery` showing a skipToken type-check error. This seems to be Typescript taking the wrong method overload for `infiniteQueryOptions` because 1 overload has the second parameter object set as optional, and that overload also supports skipToken for compatibility with `useInfiniteQuery`

This PR removes the optional from the second argument because getNextPageParam is mandatory, and adds a regression suite to both document and compare behaviour to Tanstack Query

```ts
import { infiniteQueryOptions } from '@tanstack/react-query';

// this gives a type checking error
infiniteQueryOptions({
  queryFn: skipToken,
  queryKey: [1],
  initialPageParam: 0,
  initialData: { pages: [], pageParams: [] },
  // This is a must!
  // getNextPageParam() {
  //   return 2
  // }
});

// tRPC does not provide a default for getNextPageParam and its 
// types by design just carry through the same constraints as @tanstack/react-query

// Therefore this must be invalid in tRPC
const queryOptions = trpc.post.list.infiniteQueryOptions(inputOnly)

// and this must be required
const queryOptions = trpc.post.list.infiniteQueryOptions(
  {},
  {
    getNextPageParam(lastPage) {
      return lastPage.next;
    },
  },
);


```

## ✅ Checklist

- [ ] I have followed the steps listed in the [Contributing guide](https://github.com/trpc/trpc/blob/main/CONTRIBUTING.md).
- [ ] If necessary, I have added documentation related to the changes made.
- [ ] I have added or updated the tests related to the changes made.


<!-- This is an auto-generated comment: release notes by coderabbit.ai -->
## Summary by CodeRabbit

* **Bug Fixes**
  * Stronger type safety: options are now required for infinite queries when using skip tokens, preventing ambiguous optional usage and inconsistent overloads.

* **Tests**
  * Added and expanded regression tests covering skip

