+async function setupPerfInstrumentation(page: Page): Promise<void> {
+  await page.evaluate(() => {
+    const contentEditable = document.querySelector('[contenteditable="true"]')
+    if (!contentEditable) {
+      throw new Error('Could not find contentEditable element')
