+ 
+-  border-color: tomato;
++border-color : tomato
++    ;
++
+ `;
+ 
+ Button.extend.attr({})`
+-  border-color: black;
++border-color : black;
+ `;
+ 
+ styled(ExistingComponent)`
+   color: papayawhip;
+
